"""Writes the images that the Draw3D2 tests (tests/suite/draw3d2_*_pixels.bb) draw: square, power of two, as Draw3D2 wants.

usage: generate_draw3d2_images.py tests/draw3d2/images
"""
import sys
from pathlib import Path

from PIL import Image, ImageDraw, ImageFont


def white(path):
    Image.new("RGBA", (32, 32), (255, 255, 255, 255)).save(path)


def sprite(path):
    """64x64: four colored quarters, a soft transparent edge, a black cross, opaque in the middle."""
    img = Image.new("RGBA", (64, 64), (0, 0, 0, 0))
    px = img.load()
    colors = [(255, 64, 64), (64, 255, 64), (64, 64, 255), (255, 255, 64)]
    for y in range(64):
        for x in range(64):
            dx, dy = x - 31.5, y - 31.5
            d = (dx * dx + dy * dy) ** 0.5
            if d > 30:
                continue
            c = colors[(1 if x >= 32 else 0) + (2 if y >= 32 else 0)]
            a = 255 if d < 22 else int(255 * (30 - d) / 8)
            if abs(dx) < 1.5 or abs(dy) < 1.5:
                c = (0, 0, 0)
            px[x, y] = (c[0], c[1], c[2], a)
    img.save(path)


def font(path):
    """256x256, 16x16 cells in ASCII order, white glyphs on transparent."""
    img = Image.new("RGBA", (256, 256), (0, 0, 0, 0))
    glyphs = Image.new("L", (256, 256), 0)
    draw = ImageDraw.Draw(glyphs)
    f = ImageFont.load_default()
    for code in range(32, 128):
        cx, cy = (code % 16) * 16, (code // 16) * 16
        draw.text((cx + 3, cy + 2), chr(code), fill=255, font=f)
    # Hard edged: any lit pixel is opaque, so the font does not depend on how it is filtered.
    px, g = img.load(), glyphs.load()
    for y in range(256):
        for x in range(256):
            if g[x, y] > 100:
                px[x, y] = (255, 255, 255, 255)
    img.save(path)


if __name__ == "__main__":
    out = Path(sys.argv[1])
    out.mkdir(parents=True, exist_ok=True)
    white(out / "white.png")
    sprite(out / "sprite.png")
    font(out / "font.png")
